import time
from collections import defaultdict

class RateLimiter:
    def __init__(self, n=10, per=60):
        self.n = n
        self.per = per
        self.d = defaultdict(list)
    def allow(self, key):
        now = time.time()
        lst = self.d[key]
        while lst and lst[0] <= now - self.per:
            lst.pop(0)
        if len(lst) < self.n:
            lst.append(now)
            return True
        return False

