import time
from collections import defaultdict

class RateLimiter:
    def __init__(self, max_count=5, window=60):
        self.d = defaultdict(list)
        self.max_count = max_count
        self.window = window

    def allow(self, key):
        t = time.time()
        q = self.d[key]
        while q and q[0] <= t - self.window:
            q.pop(0)
        if len(q) < self.max_count:
            q.append(t)
            return True
        return False

