import time
from collections import defaultdict

class RateLimiter:
    def __init__(self, limit=10, period=60):
        self.d = defaultdict(list)
        self.limit = limit
        self.period = period

    def allow(self, key):
        now = time.time()
        t = self.d[key]
        while t and t[0] <= now - self.period:
            t.pop(0)
        if len(t) < self.limit:
            t.append(now)
            return True
        return False

